package org.json;import java.util.*;public class JSONObject{final Map<String,Object> v=new HashMap<>();public JSONObject(){}public JSONObject put(String k,Object o){v.put(k,o);return this;}public String optString(String k){return optString(k,"");}public String optString(String k,String d){Object o=v.get(k);return o==null?d:String.valueOf(o);}public long optLong(String k){return v.get(k) instanceof Number?((Number)v.get(k)).longValue():0;}public long optLong(String k,long d){return v.containsKey(k)?optLong(k):d;}public long getLong(String k){return ((Number)v.get(k)).longValue();}public boolean has(String k){return v.containsKey(k);}}